import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-106: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short106', durationInSeconds: 28.5, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(3.0);
const B2 = secToFrame(7.8);
const B3 = secToFrame(11.2);
const B4 = secToFrame(14.8);
const B5 = secToFrame(18.5);
const CTA = secToFrame(26.4);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const HOOK = [{ text: 'GOOGLE AI MUSIC' }, { text: '8¢ A SONG', accent: true }];

const Short106: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-106/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="AI MUSIC PRICING" lines={HOOK} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Lyria 3.5" tagline="Google's full-song music model." chip="$0.08" at={B1 + 4}>
          <Panel>
            <Line k="full song" v="$0.08" good />
            <Line k="via" v="Gemini API" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="No free tier" tagline="Every song is billed." chip="PAID" at={B2 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Lyria 3.5 free tier" v="not available" bad />
            <Line k="billing" v="per song" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Lyria 3 Clip" tagline="The older 30-second clip." chip="$0.04" at={B3 + 4}>
          <Panel>
            <Line k="30s clip" v="$0.04" good />
            <Line k="full song (Pro)" v="$0.08" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="100 songs" tagline="Eight cents each." chip="$8" at={B4 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="1 song" v="$0.08" />
            <Line k="100 songs" v="$8.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Before you publish" tagline="Read Google's usage terms." chip="CHECK" at={B5 + 4}>
          <Panel>
            <Line k="use" v="videos, games, apps" />
            <Line k="step" v="check the terms" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-106/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI MUSIC PRICING" lines={HOOK} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 720, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Eight cents a song.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short106;
